def tx(x,y,t,c=N,s=11,w=600,a='start'): return f'<text x="{x}" y="{y}" font-size="{s}" font-weight="{w}" fill="{c}" text-anchor="{a}" font-family="Figtree,Helvetica,sans-serif">{t}</text>'
def dot(x,y,c,r=4,hollow=False): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{"none" if hollow else c}" stroke="{c}" stroke-width="1.6"/>'
